<div class="page-heading"><p class="eyebrow">Истории, которыми поделились</p><h1>Библиотека</h1><p>Здесь авторы публикуют свои рассказы. Читайте, скачивайте и обсуждайте.</p></div><form class="filter-form" method="get" action="<?= e(url('/library')) ?>"><label for="genre-filter">Жанр</label><select name="genre" id="genre-filter"><option value="">Все жанры</option><?php foreach (settings('genres') as $value => $label): ?><option value="<?= e($value) ?>"<?= $genre === $value ? ' selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select><button class="button secondary small" type="submit">Показать</button><span class="muted">Историй: <?= $result['total'] ?></span></form>
<?php if ($result['items']): ?><div class="story-grid"><?php foreach ($result['items'] as $story): ?><?php require APP_ROOT . '/views/stories/card.php'; ?><?php endforeach; ?></div><?php else: ?><div class="empty-state"><h2>Историй пока нет</h2><p><?= $genre !== '' ? 'Попробуйте выбрать другой жанр или опубликуйте свой рассказ.' : 'Здесь появятся рассказы, которые авторы решат опубликовать.' ?></p><a href="<?= e(url('/stories/new')) ?>">Создать историю →</a></div><?php endif; ?>
<?php if ($result['pages'] > 1): ?><nav class="pagination" aria-label="Страницы библиотеки"><?php for ($i = 1; $i <= $result['pages']; $i++): ?><?php if ($i === $result['page']): ?><span aria-current="page"><?= $i ?></span><?php else: ?><a href="<?= e(url('/library?genre=' . rawurlencode($genre) . '&page=' . $i)) ?>"><?= $i ?></a><?php endif; ?><?php endfor; ?></nav><?php endif; ?>
